#include <vector>

class Solution {
public:
    std::vector<int> mostVisited(int n, std::vector<int>& rounds) {
        int start = rounds.front(), end = rounds.back();
        std::vector<int> ans;
        if (start <= end) {
            for (int i = start; i <= end; ++i) ans.push_back(i);
        } else {
            for (int i = 1; i <= end; ++i) ans.push_back(i);
            for (int i = start; i <= n; ++i) ans.push_back(i);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<Integer> mostVisited(int n, int[] rounds) {
        int start = rounds[0], end = rounds[rounds.length - 1];
        List<Integer> ans = new ArrayList<>();
        if (start <= end) {
            for (int i = start; i <= end; i++) ans.add(i);
        } else {
            for (int i = 1; i <= end; i++) ans.add(i);
            for (int i = start; i <= n; i++) ans.add(i);
        }
        return ans;
    }
}

